import{_ as t,o as l,c as e,ag as o}from"./chunks/framework.D7Pdja0E.js";const u=JSON.parse('{"title":"부서 관리","description":"","frontmatter":{},"headers":[],"relativePath":"04-org-admin-guide/departments.md","filePath":"04-org-admin-guide/departments.md","lastUpdated":1776160579000}'),n={name:"04-org-admin-guide/departments.md"};function i(s,a,r,d,h,p){return l(),e("div",null,[...a[0]||(a[0]=[o(`<h1 id="부서-관리" tabindex="-1">부서 관리 <a class="header-anchor" href="#부서-관리" aria-label="Permalink to &quot;부서 관리&quot;">​</a></h1><p>기관 관리자는 조직의 부서 구조를 설정하고 관리합니다.</p><h2 id="부서-목록" tabindex="-1">부서 목록 <a class="header-anchor" href="#부서-목록" aria-label="Permalink to &quot;부서 목록&quot;">​</a></h2><p>관리 &gt; <strong>부서 관리</strong> 메뉴에서 전체 부서 목록을 트리 형태로 확인합니다.</p><h3 id="인원수-표시" tabindex="-1">인원수 표시 <a class="header-anchor" href="#인원수-표시" aria-label="Permalink to &quot;인원수 표시&quot;">​</a></h3><p>각 부서 옆에 표시되는 인원수는 <strong>하위 부서를 포함한 전체 인원수</strong>입니다.</p><ul><li>예: 경영지원본부(10) — 경영지원본부 직접 소속 + 하위 부서(인사팀, 총무팀 등) 인원 합산</li><li>하위 부서가 없는 경우 해당 부서의 직접 소속 인원수가 표시됩니다</li><li>부서를 선택하면 상세 패널에서 직접 소속 인원수와 하위 포함 전체 인원수를 함께 확인할 수 있습니다</li></ul><h2 id="부서-생성" tabindex="-1">부서 생성 <a class="header-anchor" href="#부서-생성" aria-label="Permalink to &quot;부서 생성&quot;">​</a></h2><ol><li><strong>&quot;+ 부서 추가&quot;</strong> 버튼을 클릭합니다.</li><li>부서 이름을 입력합니다.</li><li>상위 부서를 선택합니다 (최상위 부서인 경우 비워둡니다).</li><li><strong>&quot;생성&quot;</strong> 버튼을 클릭합니다.</li></ol><h2 id="부서-수정" tabindex="-1">부서 수정 <a class="header-anchor" href="#부서-수정" aria-label="Permalink to &quot;부서 수정&quot;">​</a></h2><ol><li>부서 목록에서 대상 부서를 선택합니다.</li><li>부서 이름, 상위 부서를 수정합니다.</li><li>변경 사항을 저장합니다.</li></ol><h2 id="부서-삭제" tabindex="-1">부서 삭제 <a class="header-anchor" href="#부서-삭제" aria-label="Permalink to &quot;부서 삭제&quot;">​</a></h2><ol><li>부서 상세에서 <strong>&quot;삭제&quot;</strong> 버튼을 클릭합니다.</li><li>하위 부서가 있는 경우 삭제할 수 없습니다. 하위 부서를 먼저 이동하거나 삭제해야 합니다.</li><li>소속 구성원이 있는 경우 다른 부서로 이동 후 삭제합니다.</li></ol><h2 id="부서-일괄-등록" tabindex="-1">부서 일괄 등록 <a class="header-anchor" href="#부서-일괄-등록" aria-label="Permalink to &quot;부서 일괄 등록&quot;">​</a></h2><p>CSV 파일을 이용하여 부서를 일괄 등록할 수 있습니다.</p><h3 id="템플릿-다운로드" tabindex="-1">템플릿 다운로드 <a class="header-anchor" href="#템플릿-다운로드" aria-label="Permalink to &quot;템플릿 다운로드&quot;">​</a></h3><ol><li>부서 관리 화면에서 <strong>&quot;일괄 등록&quot;</strong> 버튼을 클릭합니다.</li><li><strong>&quot;템플릿 다운로드&quot;</strong> 버튼으로 CSV 템플릿 파일을 다운로드합니다.</li></ol><h3 id="csv-형식" tabindex="-1">CSV 형식 <a class="header-anchor" href="#csv-형식" aria-label="Permalink to &quot;CSV 형식&quot;">​</a></h3><table tabindex="0"><thead><tr><th>컬럼</th><th>필수</th><th>설명</th></tr></thead><tbody><tr><td>name</td><td>O</td><td>부서 이름</td></tr><tr><td>code</td><td>O</td><td>부서 코드 (고유값)</td></tr><tr><td>parent_code</td><td></td><td>상위 부서 코드 (최상위인 경우 비워둡니다)</td></tr></tbody></table><p><strong>예시:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>name,code,parent_code</span></span>
<span class="line"><span>경영지원본부,MGMT,</span></span>
<span class="line"><span>인사팀,HR,MGMT</span></span>
<span class="line"><span>총무팀,GA,MGMT</span></span>
<span class="line"><span>개발본부,DEV,</span></span>
<span class="line"><span>프론트엔드팀,FE,DEV</span></span>
<span class="line"><span>백엔드팀,BE,DEV</span></span></code></pre></div><h3 id="미리보기" tabindex="-1">미리보기 <a class="header-anchor" href="#미리보기" aria-label="Permalink to &quot;미리보기&quot;">​</a></h3><ol><li>CSV 파일을 드래그 앤 드롭하거나 파일 선택으로 업로드합니다.</li><li><strong>미리보기</strong> 화면에서 등록될 부서 목록을 확인합니다.</li><li>오류가 있는 행은 빨간색으로 표시되며, 오류 내용이 함께 표시됩니다.</li></ol><h3 id="실행" tabindex="-1">실행 <a class="header-anchor" href="#실행" aria-label="Permalink to &quot;실행&quot;">​</a></h3><ol><li>미리보기에서 오류가 없는 것을 확인한 후 <strong>&quot;등록 실행&quot;</strong> 버튼을 클릭합니다.</li><li>등록 결과가 표시됩니다 (성공/실패 건수).</li></ol><blockquote><p><strong>참고</strong>: 부서 일괄 등록은 부서 구조만 변경합니다. 구성원 배정은 초대 시 부서를 지정하거나, 사용자가 프로필에서 직접 변경할 수 있습니다.</p></blockquote><h2 id="부서-통폐합" tabindex="-1">부서 통폐합 <a class="header-anchor" href="#부서-통폐합" aria-label="Permalink to &quot;부서 통폐합&quot;">​</a></h2><p>두 부서를 하나로 합칠 수 있습니다.</p><ol><li>부서 목록에서 통폐합할 부서를 선택합니다.</li><li>상세 패널에서 <strong>&quot;통폐합&quot;</strong> 버튼을 클릭합니다.</li><li>대상 부서를 선택합니다.</li><li><strong>&quot;통합&quot;</strong> 버튼을 클릭하면 선택한 부서의 구성원과 하위 부서가 대상 부서로 이동되고, 원래 부서는 삭제됩니다.</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>통폐합은 되돌릴 수 없습니다. 실행 전에 대상 부서를 신중하게 확인하세요.</p></div>`,30)])])}const g=t(n,[["render",i]]);export{u as __pageData,g as default};
